1	// Command darksafe is the 零信任身份与授权决策平台 entry point.
2	package main
3	
4	import (
5		"encoding/json"
6		"fmt"
7		"os"
8	
9		"github.com/asdhoaiqqq/darksafe-access/darksafe"
10	)
11	
12	func main() {
13		command := "demo"
14		if len(os.Args) > 1 {
15			command = os.Args[1]
16		}
17		switch command {
18		case "demo":
19			runDemo()
20		case "version":
21			fmt.Println("darksafe 0.1.0")
22		case "plan":
23			runPlan(os.Args[2:])
24		case "help", "-h", "--help":
25			usage()
26		default:
27			fmt.Fprintf(os.Stderr, "unknown command %q\n", command)
28			usage()
29			os.Exit(2)
30		}
31	}
32	
33	func usage() {
34		fmt.Println("usage: darksafe [demo|version|plan <JSON文件路径>|help]")
35		fmt.Println()
36		fmt.Println("  demo             运行内置演示")
37		fmt.Println("  version          显示版本号")
38		fmt.Println("  plan <JSON路径>  离线读取发布配置并输出发布计划（JSON），不连接集群、不执行发布")
39		fmt.Println("  help             显示本帮助")
40		fmt.Println()
41		fmt.Println("plan 输入字段：app, revision, image, batchSize, clusters[], include[], exclude[], spreadBy（可选）")
42		fmt.Println("plan 成功时向标准输出写入完整发布计划；失败时以非零状态退出，并在标准错误说明具体问题。")
43	}
44	
45	func runPlan(args []string) {
46		if len(args) != 1 {
47			fmt.Fprintln(os.Stderr, "用法: darksafe plan <JSON文件路径>")
48			os.Exit(2)
49		}
50		data, err := os.ReadFile(args[0])
51		if err != nil {
52			fmt.Fprintf(os.Stderr, "无法读取文件: %v\n", err)
53			os.Exit(1)
54		}
55		in, err := darksafe.ParseReleaseInput(data)
56		if err != nil {
57			fmt.Fprintln(os.Stderr, err)
58			os.Exit(1)
59		}
60		plan, err := darksafe.MakeReleasePlan(in)
61		if err != nil {
62			fmt.Fprintln(os.Stderr, err)
63			os.Exit(1)
64		}
65		out, err := json.MarshalIndent(plan, "", "  ")
66		if err != nil {
67			fmt.Fprintf(os.Stderr, "序列化发布计划失败: %v\n", err)
68			os.Exit(1)
69		}
70		fmt.Println(string(out))
71	}
72	
73	func runDemo() {
74		subjects := []darksafe.Subject{
75			{ID: "u-1001", Kind: "user", Roles: []string{"org/payments/ledger:read"}},
76			{ID: "svc-batch", Kind: "service", Roles: []string{"owner"}},
77			{ID: "u-1002", Kind: "user", Disabled: true},
78		}
79		resource := darksafe.Resource{ID: "ledger-main", Scope: "org/payments/ledger"}
80		allowed := 0
81		for _, subject := range subjects {
82			decision := darksafe.Access(subject, resource, "read")
83			if decision.Allowed {
84				allowed++
85			}
86			fmt.Printf("subject=%s allowed=%v reason=%s\n", subject.ID, decision.Allowed, decision.Reason)
87		}
88		fmt.Printf("summary: %d of %d subjects allowed\n", allowed, len(subjects))
89	}
